- 	/* interpolate */
- 	if (right == left || !lower_lum)
- 		lum = upper_lum;
- 	else
- 		lum = lower_lum + DIV_ROUND_CLOSEST((upper_lum - lower_lum) *
- 						    (brightness - lower_signal),
- 						    upper_signal - lower_signal);
